package org.example.server.reconciliation;
import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/bank-statements")
public class BankReconciliationController {
 private final BankReconciliationService service; private final BankReconciliationRuleService ruleService; public BankReconciliationController(BankReconciliationService service, BankReconciliationRuleService ruleService){this.service=service;this.ruleService=ruleService;}
 @PostMapping("/imports") public BankReconciliationDtos.ImportResult importStatement(@RequestBody BankReconciliationDtos.ImportRequest r){return service.importStatement(r);}
 @PostMapping("/imports/continuity-check") public BankReconciliationDtos.ContinuityCheckResult checkContinuity(@RequestBody BankReconciliationDtos.ContinuityCheckRequest r){return service.checkContinuity(r);}
 @GetMapping("/imports") public List<BankReconciliationDtos.BatchDto> batches(){return service.batches();}
 @GetMapping("/imports/page") public BankReconciliationDtos.BatchPage batchPage(@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="50") int size,@RequestParam(defaultValue="") String account,@RequestParam(defaultValue="") String status,@RequestParam(defaultValue="") String fromDate,@RequestParam(defaultValue="") String toDate,@RequestParam(defaultValue="") String q){return service.batchPage(page,size,account,status,fromDate,toDate,q);}
 @GetMapping("/imports/{id}") public BankReconciliationDtos.BatchDto batch(@PathVariable Long id){return service.batch(id);}
 @GetMapping("/imports/{id}/source") public BankReconciliationDtos.SourceDto source(@PathVariable Long id){return service.source(id);}
 @DeleteMapping("/imports/{id}") public BankReconciliationDtos.BatchDeleteResult deleteBatch(@PathVariable Long id,@RequestParam String confirmation,@RequestParam(required=false) String user){return service.deleteBatch(id,confirmation,user);}
 @GetMapping("/imports/{id}/transactions") public List<BankReconciliationDtos.TransactionDto> transactions(@PathVariable Long id){return service.transactions(id);}
 @GetMapping("/imports/{id}/page") public BankReconciliationDtos.TransactionPage page(@PathVariable Long id,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="50") int size,@RequestParam(defaultValue="") String status,@RequestParam(defaultValue="ALL") String direction,@RequestParam(defaultValue="ALL") String channel,@RequestParam(defaultValue="") String fromDate,@RequestParam(defaultValue="") String toDate,@RequestParam(defaultValue="") String q){return service.transactionPage(id,"",page,size,status,direction,channel,fromDate,toDate,q);}
 @GetMapping("/accounts/page") public BankReconciliationDtos.TransactionPage accountPage(@RequestParam(defaultValue="") String account,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="50") int size,@RequestParam(defaultValue="") String status,@RequestParam(defaultValue="ALL") String direction,@RequestParam(defaultValue="ALL") String channel,@RequestParam(defaultValue="") String fromDate,@RequestParam(defaultValue="") String toDate,@RequestParam(defaultValue="") String q){return service.transactionPage(0L,account,page,size,status,direction,channel,fromDate,toDate,q);}
 @GetMapping("/accounts/metrics") public BankReconciliationDtos.Metrics accountMetrics(@RequestParam(defaultValue="") String account,@RequestParam(defaultValue="") String fromDate,@RequestParam(defaultValue="") String toDate){return service.accountMetrics(account,fromDate,toDate);}
 @GetMapping("/imports/{id}/brs") public BankReconciliationDtos.BrsSummaryDto batchBrs(@PathVariable Long id){return service.getBrsSummary(id,"","","");}
 @GetMapping("/accounts/brs") public BankReconciliationDtos.BrsSummaryDto accountBrs(@RequestParam(defaultValue="") String account,@RequestParam(defaultValue="") String fromDate,@RequestParam(defaultValue="") String toDate){return service.getBrsSummary(0L,account,fromDate,toDate);}
 @GetMapping("/imports/{id}/metrics") public BankReconciliationDtos.Metrics metrics(@PathVariable Long id){return service.metrics(id);}
 @PostMapping("/transactions/{id}/suggest") public List<BankReconciliationDtos.CandidateDto> suggest(@PathVariable Long id){return service.suggest(id);}
 @GetMapping("/transactions/{id}") public BankReconciliationDtos.TransactionDto transaction(@PathVariable Long id){return service.transaction(id);}
 @GetMapping("/transactions/{id}/candidates") public List<BankReconciliationDtos.CandidateDto> candidates(@PathVariable Long id){return service.candidates(id);}
 @PostMapping("/transactions/{id}/match") public BankReconciliationDtos.OperationResult match(@PathVariable Long id,@RequestBody BankReconciliationDtos.MatchRequest r){return service.match(id,r);}
 @PostMapping("/transactions/{id}/expense") public BankReconciliationDtos.OperationResult expense(@PathVariable Long id,@RequestBody BankReconciliationDtos.ExpenseRequest r){return service.expense(id,r);}
 @PostMapping("/transactions/{id}/bank-entry") public BankReconciliationDtos.OperationResult bankEntry(@PathVariable Long id,@RequestBody BankReconciliationDtos.BankEntryRequest r){return service.bankEntry(id,r);}
 @PostMapping("/transactions/bulk/expense") public BankReconciliationDtos.BulkOperationResult bulkExpense(@RequestBody BankReconciliationDtos.BulkExpenseRequest r){return service.bulkExpense(r);}
 @PostMapping("/transactions/bulk/bank-entry") public BankReconciliationDtos.BulkOperationResult bulkBankEntry(@RequestBody BankReconciliationDtos.BulkBankEntryRequest r){return service.bulkBankEntry(r);}
 @PostMapping("/transactions/{id}/note") public BankReconciliationDtos.OperationResult note(@PathVariable Long id,@RequestBody BankReconciliationDtos.NoteRequest r){return service.updateNote(id,r);}
 @PostMapping("/transactions/{id}/ignore") public BankReconciliationDtos.OperationResult ignore(@PathVariable Long id,@RequestBody BankReconciliationDtos.IgnoreRequest r){return service.ignore(id,r);}
 @PostMapping("/transactions/{id}/review") public BankReconciliationDtos.OperationResult review(@PathVariable Long id,@RequestBody BankReconciliationDtos.NoteRequest r){return service.review(id,r);}
 @PostMapping("/transactions/{id}/reverse") public BankReconciliationDtos.OperationResult reverse(@PathVariable Long id,@RequestParam(required=false) String user){return service.reverse(id,user);}
 @GetMapping("/transactions/{id}/audit") public List<BankReconciliationDtos.AuditDto> audit(@PathVariable Long id){return service.audit(id);}
 @GetMapping("/linkage") public BankReconciliationDtos.DocumentLinkageDto getLinkage(@RequestParam(required=false) String type, @RequestParam(required=false) Integer id, @RequestParam(required=false) String docNo, @RequestParam(required=false) Long transactionId, @RequestParam(required=false) Integer financeId){return service.getLinkage(type, id, docNo, transactionId, financeId);}
 @GetMapping("/rules") public List<BankReconciliationDtos.RuleDto> listRules(){return ruleService.listRules();}
 @PostMapping("/rules") public BankReconciliationDtos.RuleDto createRule(@RequestBody BankReconciliationDtos.RuleSaveRequest r){return ruleService.saveRule(null, r);}
 @PutMapping("/rules/{id}") public BankReconciliationDtos.RuleDto updateRule(@PathVariable Long id, @RequestBody BankReconciliationDtos.RuleSaveRequest r){return ruleService.saveRule(id, r);}
 @DeleteMapping("/rules/{id}") public Map<String, Object> deleteRule(@PathVariable Long id){ruleService.deleteRule(id); return Map.of("deleted", true, "id", id);}
 @PostMapping("/imports/{id}/rules/preview") public BankReconciliationDtos.RulePreviewResult previewRules(@PathVariable Long id, @RequestBody(required=false) BankReconciliationDtos.RuleSaveRequest candidate){return ruleService.previewBatch(id, candidate);}
 @PostMapping("/imports/{id}/rules/apply") public BankReconciliationDtos.RuleApplyResult applyRules(@PathVariable Long id, @RequestParam(required=false) String user){return ruleService.applyRulesToBatch(id, false, user);}
 @PostMapping("/imports/{id}/rules/{ruleId}/apply") public BankReconciliationDtos.RuleApplyResult applySingleRule(@PathVariable Long id, @PathVariable Long ruleId, @RequestParam(required=false) String user){return ruleService.applySingleRuleToBatch(id, ruleId, user);}
 @PostMapping("/transactions/{txId}/rules/{ruleId}/apply") public BankReconciliationDtos.OperationResult applyRuleToTx(@PathVariable Long txId, @PathVariable Long ruleId, @RequestParam(required=false) String user){return ruleService.executeRuleForTransaction(txId, ruleId, user);}
 @GetMapping("/rules/suggestions") public List<BankReconciliationDtos.RuleSuggestionCandidateDto> discoverRuleSuggestions(){return ruleService.discoverRuleSuggestions();}
 @GetMapping("/rules/parties") public List<BankReconciliationDtos.PartyOptionDto> listRuleParties(){return ruleService.listActiveParties();}
 @GetMapping("/imports/{id}/auto-match/preview") public BankReconciliationDtos.AutoMatchPreviewDto previewAutoMatchBatch(@PathVariable Long id){return service.previewAutoMatch(id, "", "", "");}
 @GetMapping("/accounts/auto-match/preview") public BankReconciliationDtos.AutoMatchPreviewDto previewAutoMatchAccount(@RequestParam(defaultValue="") String account,@RequestParam(defaultValue="") String fromDate,@RequestParam(defaultValue="") String toDate){return service.previewAutoMatch(0L, account, fromDate, toDate);}
}
